#include <cctype>
#include <cstdint>
#include <optional>
#include <string>

struct Frame { std::string module; std::string function; std::uint64_t offset; };

std::optional<Frame> parseFrame(const std::string& text)
{
    const std::size_t plus{ text.rfind("+0x") != std::string::npos ? text.rfind("+0x") : text.rfind("+0X") };
    if (plus == std::string::npos || plus == 0) return std::nullopt;
    const std::string hex{ text.substr(plus + 3) };
    if (hex.empty() || hex.size() > 16) return std::nullopt;
    std::uint64_t offset{ 0 };
    for (char c : hex)
    {
        if (!std::isxdigit(static_cast<unsigned char>(c))) return std::nullopt;
        const int digit{ std::isdigit(static_cast<unsigned char>(c)) ? c - '0' : std::tolower(static_cast<unsigned char>(c)) - 'a' + 10 };
        offset = offset * 16 + static_cast<std::uint64_t>(digit);
    }
    const std::string head{ text.substr(0, plus) };
    const std::size_t bang{ head.find('!') };
    Frame f{ head, "", offset };
    if (bang != std::string::npos) { f.module = head.substr(0, bang); f.function = head.substr(bang + 1); }
    if (f.module.empty()) return std::nullopt;
    return f;
}

unitTests:
TEST("with a function") { const auto f{ parseFrame("game.exe!Player::update+0x2a") }; CHECK(f.has_value()); CHECK_EQ(f->module, std::string("game.exe")); CHECK_EQ(f->function, std::string("Player::update")); CHECK_EQ(f->offset, 0x2Aull); }
TEST("without symbols") { const auto f{ parseFrame("ntdll.dll+0x1F00") }; CHECK_EQ(f->module, std::string("ntdll.dll")); CHECK(f->function.empty()); CHECK_EQ(f->offset, 0x1F00ull); }
TEST("templates and spaces") { const auto f{ parseFrame("engine.dll!std::vector<int, std::allocator<int> >::push_back+0x10") }; CHECK_EQ(f->function, std::string("std::vector<int, std::allocator<int> >::push_back")); CHECK_EQ(f->offset, 0x10ull); }
TEST("upper-case X") { CHECK_EQ(parseFrame("a.exe+0XFF")->offset, 0xFFull); }
TEST("big offsets") { CHECK_EQ(parseFrame("a.exe+0x7ff6a1235f10")->offset, 0x7FF6A1235F10ull); }
TEST("not a frame") { CHECK(!parseFrame("no offset here")); CHECK(!parseFrame("+0x10")); CHECK(!parseFrame("a.exe+0x")); CHECK(!parseFrame("a.exe+0xZZ")); CHECK(!parseFrame("!f+0x1")); }

